inline std::complex<double>
operator+(int lhs, const std::complex<double>& rhs)
{
    return std::complex<double>(static_cast<double>(lhs), 0.0) + rhs;
}
   template <typename T>
std::complex<T> operator*(int lhs, const std::complex<T>& rhs) {
   return static_cast<T>(lhs) * rhs;
}

inline double Csc(double x) {
return 1.0 / sin(x);
}

inline double Sec(double x) {
return 1.0 / cos(x);
}

inline double Cot(double x) {
return std::tan(M_PI_2 - x);
}

std::complex<double> DT::A1A1TtTree(const double &cos_t, const double &s)
{
    std::complex<double> MHSqcomp = std::complex<double>(MH*MH,-MH*WH);
    std::complex<double> MS1Sqcomp = std::complex<double>(MS1*MS1,-MS1*WS1);

    return (MT*s*((MHSqcomp) - (MS1Sqcomp))*(s - 4*(MT*MT))*sin(2*alpha))/(svev*vev*(-s + (MHSqcomp))*(-s + (MS1Sqcomp)));
    }

std::complex<double> DT::A1A1TtTreeConj(const double &cos_t, const double &s)
{
    std::complex<double> MHSqcomp = std::complex<double>(MH*MH,-MH*WH);
    std::complex<double> MS1Sqcomp = std::complex<double>(MS1*MS1,-MS1*WS1);

    return (MT*s*cos(alpha)*((conj(sqrt(MHSqcomp))*conj(sqrt(MHSqcomp))) - (conj(sqrt(MS1Sqcomp))*conj(sqrt(MS1Sqcomp))))*sin(alpha))/(svev*vev*(s - (conj(sqrt(MHSqcomp))*conj(sqrt(MHSqcomp))))*(s - (conj(sqrt(MS1Sqcomp))*conj(sqrt(MS1Sqcomp)))));
    }

